pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.sendTo(address(0x1234), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == (caller == address(this)));
    }
